import threading

class SafeBoard:
    def __init__(self):
        self._data, self._lock = {}, threading.Lock()
    def append(self, key, value):
        with self._lock:                      # critical section
            items = self._data.get(key, [])
            items.append(value)               # no other writer can interleave
            self._data[key] = items
# every append is atomic -> no lost updates under concurrency

