class Blackboard:
    def __init__(self):
        self._data = {}
    def read(self, key):
        # each agent gets its own snapshot, as with a real remote store
        return list(self._data.get(key, []))
    def write(self, key, value):
        self._data[key] = value

bb = Blackboard()
bb.write("findings", [])

# simulate a race: both agents read the SAME stale value before either writes
a_view = bb.read("findings")   # []  (agent A's stale snapshot)
b_view = bb.read("findings")   # []  (agent B's stale snapshot)

a_view.append("A: found X"); bb.write("findings", a_view)
b_view.append("B: found Y"); bb.write("findings", b_view)  # clobbers A

print(bb.read("findings"))   # A's finding was lost

import threading

class SafeBoard:
    def __init__(self):
        self._data = {}
        self._lock = threading.Lock()
    def append(self, key, value):
        with self._lock:                     # serialize read-modify-write
            items = self._data.get(key, [])
            items.append(value)
            self._data[key] = items
    def read(self, key):
        with self._lock:
            return list(self._data.get(key, []))

bb = SafeBoard()

def worker(name, n):
    for i in range(n):
        bb.append("findings", f"{name}-{i}")

threads = [threading.Thread(target=worker, args=(name, 50))
           for name in ("A", "B", "C")]
for t in threads: t.start()
for t in threads: t.join()

print(len(bb.read("findings")))   # all 150 appends survive

