import threading

class Blackboard:
    def __init__(self):
        self._data = {}
        self._lock = threading.Lock()

    def read(self, key):
        with self._lock:
            value = self._data.get(key)
            # return a copy of lists so callers can't mutate internal state
            return list(value) if isinstance(value, list) else value

    def write(self, key, value):
        with self._lock:
            self._data[key] = value

    def append(self, key, value):
        # whole read-modify-write inside one critical section => no lost updates
        with self._lock:
            items = self._data.get(key)
            if items is None:
                items = []
                self._data[key] = items
            items.append(value)

    def update(self, key, fn):
        # atomic read-modify-write: apply fn to the current value and store it
        with self._lock:
            self._data[key] = fn(self._data.get(key))

