import threading

class Blackboard:
    def __init__(self):
        self._data = {}
        self._lock = threading.Lock()

    def read(self, key):
        with self._lock:
            v = self._data.get(key)
            return list(v) if isinstance(v, list) else v

    def write(self, key, value):
        with self._lock:
            self._data[key] = value

    def append(self, key, value):
        with self._lock:                     # atomic read-modify-write
            items = self._data.get(key)
            if items is None:
                items = []
                self._data[key] = items
            items.append(value)

    def update(self, key, fn):
        with self._lock:
            self._data[key] = fn(self._data.get(key))

if __name__ == "__main__":
    bb = Blackboard()
    def worker(name):
        for i in range(100):
            bb.append("findings", f"{name}-{i}")
    ts = [threading.Thread(target=worker, args=(n,)) for n in ("A", "B", "C")]
    for t in ts: t.start()
    for t in ts: t.join()
    print(len(bb.read("findings")))   # 300, no lost updates
